from pathlib import Path

compact = Path('lib/core/widgets/compact_nav_controls.dart')
text = compact.read_text(encoding='utf-8')
text = text.replace(
    "const double kAppCompactControlHeight = 44;\nconst double kAppCompactControlFontSize = 12;",
    "const double kAppCompactControlHeight = 44;\nconst double kAppQuickEntryControlHeight = 40;\nconst double kAppCompactControlFontSize = 12;",
    1,
)
old = '''/// Canonical quick-entry line shared by desktop Planning and Timeline.\n/// The field and action are deliberately the same 44px height and 12px radius.\nclass AppQuickEntryRow extends StatelessWidget {'''
new = '''/// Canonical input surface shared with the Notes library.\n///\n/// This is the Notes quick-add/search field promoted to core so Planning,\n/// Timeline and Notes cannot drift to different input geometry or surfaces.\nclass AppLibraryInput extends StatefulWidget {\n  const AppLibraryInput({\n    super.key,\n    required this.controller,\n    required this.focusNode,\n    required this.hintText,\n    required this.textInputAction,\n    this.textCapitalization = TextCapitalization.none,\n    this.onChanged,\n    this.onSubmitted,\n    this.suffixIcon,\n    this.showSearchIcon = true,\n  });\n\n  final TextEditingController controller;\n  final FocusNode focusNode;\n  final String hintText;\n  final TextInputAction textInputAction;\n  final TextCapitalization textCapitalization;\n  final ValueChanged<String>? onChanged;\n  final ValueChanged<String>? onSubmitted;\n  final Widget? suffixIcon;\n  final bool showSearchIcon;\n\n  @override\n  State<AppLibraryInput> createState() => _AppLibraryInputState();\n}\n\nclass _AppLibraryInputState extends State<AppLibraryInput> {\n  bool _hovered = false;\n\n  @override\n  void initState() {\n    super.initState();\n    widget.focusNode.addListener(_handleFocusChanged);\n  }\n\n  @override\n  void didUpdateWidget(covariant AppLibraryInput oldWidget) {\n    super.didUpdateWidget(oldWidget);\n    if (oldWidget.focusNode == widget.focusNode) return;\n    oldWidget.focusNode.removeListener(_handleFocusChanged);\n    widget.focusNode.addListener(_handleFocusChanged);\n  }\n\n  @override\n  void dispose() {\n    widget.focusNode.removeListener(_handleFocusChanged);\n    super.dispose();\n  }\n\n  void _handleFocusChanged() {\n    if (mounted) setState(() {});\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    final scheme = theme.colorScheme;\n    final dark = theme.brightness == Brightness.dark;\n    final meta = dark\n        ? scheme.onSurfaceVariant.withValues(alpha: 0.92)\n        : const Color(0xFF94A3B8);\n    final normalFill = dark\n        ? scheme.surfaceContainerHigh.withValues(alpha: 0.82)\n        : const Color(0xFFFFFFFF).withValues(alpha: 0.82);\n    final hoverFill = dark\n        ? scheme.surfaceContainerHighest.withValues(alpha: 0.92)\n        : const Color(0xFFFFFFFF).withValues(alpha: 0.96);\n    final normalBorder = dark\n        ? scheme.outlineVariant.withValues(alpha: 0.82)\n        : const Color(0xFFD9E0EA);\n    final focusBorder = scheme.primary.withValues(alpha: dark ? 0.86 : 0.62);\n\n    return MouseRegion(\n      onEnter: (_) => setState(() => _hovered = true),\n      onExit: (_) => setState(() => _hovered = false),\n      child: AnimatedContainer(\n        duration: const Duration(milliseconds: 90),\n        curve: Curves.easeOut,\n        height: kAppQuickEntryControlHeight,\n        decoration: BoxDecoration(\n          color: _hovered ? hoverFill : normalFill,\n          borderRadius: BorderRadius.circular(12),\n          border: Border.all(\n            color: widget.focusNode.hasFocus ? focusBorder : normalBorder,\n            width: widget.focusNode.hasFocus && dark ? 1.2 : 1,\n          ),\n        ),\n        child: TextField(\n          controller: widget.controller,\n          focusNode: widget.focusNode,\n          textInputAction: widget.textInputAction,\n          textCapitalization: widget.textCapitalization,\n          textAlignVertical: TextAlignVertical.center,\n          onChanged: widget.onChanged,\n          onSubmitted: widget.onSubmitted,\n          style: TextStyle(fontSize: 14, color: scheme.onSurface),\n          decoration: InputDecoration(\n            constraints: const BoxConstraints.tightFor(\n              height: kAppQuickEntryControlHeight,\n            ),\n            hintText: widget.hintText,\n            hintStyle: TextStyle(fontSize: 14, color: meta),\n            prefixIcon: widget.showSearchIcon\n                ? Icon(Icons.search_rounded, size: 18, color: meta)\n                : const SizedBox.shrink(),\n            prefixIconConstraints: BoxConstraints.tightFor(\n              width: widget.showSearchIcon ? kAppQuickEntryControlHeight : 0,\n              height: kAppQuickEntryControlHeight,\n            ),\n            suffixIcon: widget.suffixIcon,\n            suffixIconConstraints: widget.suffixIcon != null\n                ? const BoxConstraints.tightFor(\n                    width: kAppQuickEntryControlHeight,\n                    height: kAppQuickEntryControlHeight,\n                  )\n                : null,\n            isDense: true,\n            filled: false,\n            hoverColor: Colors.transparent,\n            contentPadding: const EdgeInsets.symmetric(horizontal: 14),\n            border: InputBorder.none,\n            enabledBorder: InputBorder.none,\n            focusedBorder: InputBorder.none,\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n/// Canonical quick-entry line shared by desktop Planning and Timeline.\n/// The field is the same component as Notes; field and action share height and radius.\nclass AppQuickEntryRow extends StatelessWidget {'''
if old not in text:
    raise SystemExit('quick-entry class marker not found')
text = text.replace(old, new, 1)
old_build = '''  @override\n  Widget build(BuildContext context) {\n    final scheme = Theme.of(context).colorScheme;\n    const radius = 12.0;\n    final enabledBorder = OutlineInputBorder(\n      borderRadius: BorderRadius.circular(radius),\n      borderSide: BorderSide(color: scheme.outline),\n    );\n    final focusedBorder = enabledBorder.copyWith(\n      borderSide: BorderSide(color: scheme.primary, width: 1.5),\n    );\n    return Row(\n      children: [\n        Expanded(\n          child: SizedBox(\n            height: kAppCompactControlHeight,\n            child: TextField(\n              controller: controller,\n              focusNode: focusNode,\n              textInputAction: TextInputAction.done,\n              onSubmitted: onSubmitted,\n              decoration: InputDecoration(\n                hintText: hintText,\n                isDense: true,\n                contentPadding: const EdgeInsets.symmetric(horizontal: 14),\n                border: enabledBorder,\n                enabledBorder: enabledBorder,\n                focusedBorder: focusedBorder,\n              ),\n            ),\n          ),\n        ),\n        const SizedBox(width: 8),\n        SizedBox(\n          height: kAppCompactControlHeight,\n          child: AppButton.primary(\n            label: actionLabel,\n            icon: actionIcon,\n            onPressed: onAction,\n            loading: loading,\n            size: AppButtonSize.m,\n          ),\n        ),\n      ],\n    );\n  }\n}'''
new_build = '''  @override\n  Widget build(BuildContext context) {\n    return Row(\n      children: [\n        Expanded(\n          child: AppLibraryInput(\n            controller: controller,\n            focusNode: focusNode,\n            hintText: hintText,\n            textInputAction: TextInputAction.done,\n            showSearchIcon: false,\n            onSubmitted: onSubmitted,\n          ),\n        ),\n        const SizedBox(width: 8),\n        SizedBox(\n          height: kAppQuickEntryControlHeight,\n          child: AppButton.primary(\n            label: actionLabel,\n            icon: actionIcon,\n            onPressed: onAction,\n            loading: loading,\n            size: AppButtonSize.m,\n          ),\n        ),\n      ],\n    );\n  }\n}'''
if old_build not in text:
    raise SystemExit('old AppQuickEntryRow build not found')
compact.write_text(text.replace(old_build, new_build, 1), encoding='utf-8')

notes = Path('lib/features/notes/notes_glm_surface.dart')
text = notes.read_text(encoding='utf-8')
text = text.replace(
    "import 'package:flutter/material.dart';",
    "import 'package:counter/core/widgets/compact_nav_controls.dart';\nimport 'package:flutter/material.dart';",
    1,
)
text = text.replace(
    'const double kNotesLibraryControlHeight = 40;',
    'const double kNotesLibraryControlHeight = kAppQuickEntryControlHeight;',
    1,
)
start = text.index('/// Canonical Notes library input used by both Search and quick-add.')
end = text.index('/// GLM glass card surface for library note cards.')
wrapper = '''/// Notes compatibility wrapper over the canonical core library input.\n/// Search, Notes quick-add, Planning and Timeline now render the same field.\nclass NotesGlmLibraryInput extends StatelessWidget {\n  const NotesGlmLibraryInput({\n    super.key,\n    required this.controller,\n    required this.focusNode,\n    required this.hintText,\n    required this.textInputAction,\n    this.textCapitalization = TextCapitalization.none,\n    this.onChanged,\n    this.onSubmitted,\n    this.suffixIcon,\n    this.showSearchIcon = true,\n  });\n\n  final TextEditingController controller;\n  final FocusNode focusNode;\n  final String hintText;\n  final TextInputAction textInputAction;\n  final TextCapitalization textCapitalization;\n  final ValueChanged<String>? onChanged;\n  final ValueChanged<String>? onSubmitted;\n  final Widget? suffixIcon;\n  final bool showSearchIcon;\n\n  @override\n  Widget build(BuildContext context) => AppLibraryInput(\n        controller: controller,\n        focusNode: focusNode,\n        hintText: hintText,\n        textInputAction: textInputAction,\n        textCapitalization: textCapitalization,\n        onChanged: onChanged,\n        onSubmitted: onSubmitted,\n        suffixIcon: suffixIcon,\n        showSearchIcon: showSearchIcon,\n      );\n}\n\n'''
notes.write_text(text[:start] + wrapper + text[end:], encoding='utf-8')

doc = Path('docs/DESIGN_SYSTEM.md')
text = doc.read_text(encoding='utf-8')
old_doc = 'Planning and Timeline use the same `AppQuickEntryRow` for their desktop entry line: field and primary action are both 44px high with the same 12px corner radius.'
new_doc = 'Planning and Timeline use the same `AppQuickEntryRow` for their desktop entry line. Its field is the canonical Notes library input promoted to core (`AppLibraryInput`), and the Add/Start primary action is locked to the same 40px height and 12px corner radius.'
if old_doc not in text:
    raise SystemExit('design-system quick-entry sentence not found')
doc.write_text(text.replace(old_doc, new_doc, 1), encoding='utf-8')
